//! 🪢️ A real source-paid return origin is admitted across unchanged quantum-one turns and returned to its issuer.
use semio_framework_job_context::testkit;
use super::*;
use crate::{OriginalJobFixtureCaller,OperationId,Generation};
use semio_framework_value::RetainedCloneGrant;
#[test]
fn return_origin_setup_and_close_preserve_the_actual_source_at_quantum_one(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let source=&fixture["source"];let stock=RetainedCloneGrant{maximum_items:source["items"].as_u64().unwrap()as usize,maximum_copy_bytes:source["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:source["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:source["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:source["depth"].as_u64().unwrap()as usize};let q=RetainedCloneGrant{maximum_items:1,..stock};let mut caller=OriginalJobFixtureCaller::admit(OperationId(7521),Generation(7),stock,||Some(0),source["deadlineUs"].as_u64().unwrap(),source["fuel"].as_u64().unwrap());let mut origin=OriginalJobReturnOrigin::empty();let mut ready=false;
 let mut refused=false;for _ in 0..fixture["returnOrigin"]["maximumSetupTurns"].as_u64().unwrap(){caller.turn(q,|cx|cx.with_original_work_loan(1,cx.original_absolute_deadline_us(),|cx|{let before=cx.retained_progress();let work=cx.original_work_units_spent();let((result,count),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||origin.admit(cx)));assert!(!heap.overflowed);if count==0{assert!(!result?)}else{assert_eq!(count,1);let error=result.unwrap_err();assert_eq!(error.primary_value().unwrap().kind,semio_framework_value::ValueRefusalKind::AllocationFailed);assert_eq!(cx.retained_progress(),before);assert_eq!(cx.original_work_units_spent()-work,1);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(origin.parent().is_ok());refused=true;}Ok(())})).unwrap();if refused{break}}assert!(refused);
 for _ in 0..fixture["returnOrigin"]["maximumSetupTurns"].as_u64().unwrap(){caller.turn(q,|cx|{cx.with_original_work_loan(1,cx.original_absolute_deadline_us(),|cx|{let before=cx.retained_progress();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||origin.admit(cx));ready=result?;let p=crate::original_failure_test_support::delta(before,cx.retained_progress());assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert!(cx.original_work_units_spent()<=1);Ok(())})}).unwrap();if ready{break}}assert!(ready);assert!(!origin.terminal_is_empty());
 let(now,deadline)=origin.original_clock().unwrap();{let(parent,receiver)=origin.context_parts().unwrap();let mut sequence=0;let mut p=crate::RetainedCloneProgress::default();let cx=parent.borrow_context(crate::StepBudget::new(1,deadline,q),now,&mut sequence,&mut p).unwrap();assert_eq!(cx.fuel_remaining(),1);assert!(cx.original_total_fuel_remaining()>1);assert!(cx.original_total_retained_grant().maximum_items>1);let claim=receiver.enter_body(&cx).unwrap().expect("actual frozen-source worker entry");claim.qualify(&cx).unwrap();}
 caller.turn(q,|cx|{let source=cx.original_source_parent()?.source_identity()?;assert_eq!(origin.parent()?.source_identity()?,source);assert_eq!(cx.fuel_remaining(),cx.original_total_fuel_remaining().min(cx.fuel_remaining()));let before=cx.retained_progress();let work=cx.original_work_units_spent();assert!(origin.admit(cx)?);assert_eq!(cx.retained_progress(),before);assert_eq!(cx.original_work_units_spent(),work);Ok(())}).unwrap();
 caller.turn(q,|cx|{let before=cx.retained_progress();let work=cx.original_work_units_spent();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let claim=origin.enter_body(cx)?.expect("genuine preclaimed body");assert_eq!(cx.retained_grant().maximum_items,1);assert!(cx.fuel_remaining()>0);claim.qualify(cx)});result?;assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),before);assert_eq!(cx.original_work_units_spent(),work);for axis in ["items","depth"]{let mut denied=q;if axis=="items"{denied.maximum_items=0}else{denied.maximum_depth=0}cx.with_retained_loan(denied,|cx|{assert!(origin.enter_body(cx)?.is_none());Ok(())})?;}cx.with_original_work_loan(0,cx.original_absolute_deadline_us(),|cx|{assert!(origin.enter_body(cx)?.is_none());Ok(())})?;assert_eq!(cx.retained_progress(),before);assert_eq!(cx.original_work_units_spent(),work);Ok(())}).unwrap();
 let mut foreign=OriginalJobFixtureCaller::admit(OperationId(7522),Generation(7),stock,||Some(0),source["deadlineUs"].as_u64().unwrap(),source["fuel"].as_u64().unwrap());foreign.turn(q,|cx|{let before=cx.retained_progress();let work=cx.original_work_units_spent();let(error,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||origin.admit(cx));assert!(error.is_err());assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),before);assert_eq!(cx.original_work_units_spent(),work);assert!(origin.close_step(cx).is_err());Ok(())}).unwrap();foreign.retire(stock);
 caller.turn(q,|cx|{let mut denied=q;denied.maximum_items=0;cx.with_retained_loan(denied,|cx|{let before=cx.retained_progress();let work=cx.original_work_units_spent();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||origin.close_step(cx));assert_eq!(result?.progress(),Default::default());assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),before);assert_eq!(cx.original_work_units_spent(),work);Ok(())})?;assert!(origin.admit(cx)?);Ok(())}).unwrap();
 caller.cancel().cancel_now();caller.turn(q,|cx|{let before=cx.retained_progress();let work=cx.original_work_units_spent();assert!(!origin.admit(cx)?);assert_eq!(cx.retained_progress(),before);assert_eq!(cx.original_work_units_spent(),work);Ok(())}).unwrap();
 for _ in 0..4096{if origin.terminal_is_empty(){break}caller.turn(q,|cx|{let before=cx.retained_progress();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||origin.close_step(cx));result?;let p=crate::original_failure_test_support::delta(before,cx.retained_progress());assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));Ok(())}).unwrap();}assert!(origin.terminal_is_empty());let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(origin));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));caller.retire(stock);
}

#[test]
fn an_actual_inherited_child_does_not_become_a_new_standalone_payer(){
 let stock=RetainedCloneGrant{maximum_items:1000000,maximum_copy_bytes:4194304,maximum_capacity_bytes:4194304,maximum_release_bytes:8388608,maximum_depth:128};let mut caller=OriginalJobFixtureCaller::admit(OperationId(7524),Generation(7),stock,||Some(0),1000000,1000000);let mut child=None;let mut origin=OriginalJobReturnOrigin::empty();caller.turn(stock,|cx|{child=Some(crate::OriginalCallerChildSource::new(cx.original_source_parent()?,cx,OperationId(7525),Generation(8))?);Ok(())}).unwrap();let mut ready=false;for _ in 0..64{caller.turn(stock,|cx|{ready=child.as_mut().unwrap().admit_step(cx.original_source_parent()?,cx)?;Ok(())}).unwrap();if ready{break}}assert!(ready);
 caller.turn(stock,|cx|{let returned=child.as_ref().unwrap().with_context(cx.original_source_parent()?,cx,stock,|child|{let before=child.retained_progress();let work=child.original_work_units_spent();let(error,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||origin.admit(child));assert_eq!(error.unwrap_err().primary_value().unwrap().kind,semio_framework_value::ValueRefusalKind::UnsupportedOwner);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(child.retained_progress(),before);assert_eq!(child.original_work_units_spent(),work);assert!(origin.terminal_is_empty());Ok(())})?;returned.into_original().unwrap_or_else(|_|panic!("actual zero-effect child receipt"))?;Ok(())}).unwrap();
 for _ in 0..4096{if child.as_ref().unwrap().terminal_is_empty(){break}caller.turn(stock,|cx|{child.as_mut().unwrap().close_step(cx.original_source_parent()?,cx)?;Ok(())}).unwrap();}assert!(child.as_ref().unwrap().terminal_is_empty());drop(child);drop(origin);caller.retire(stock);
}
